INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d63bd68-05df-579b-a48a-b63414bb638f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which protocol dynamically assigns labels in an MPLS network without traffic engineering?$$::text, $$[{"id": "A", "text": "RSVP", "is_correct": false}, {"id": "B", "text": "LDP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]$$::jsonb, $$LDP distributes labels for MPLS forwarding without requiring traffic engineering extensions.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$MPLS Fundamentals$$::text, 20.0, '615128d294aafa79', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ec80cd7-5124-512b-8dcf-b0d7411e3438', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which BGP attribute influences inbound traffic from neighboring autonomous systems?$$::text, $$[{"id": "A", "text": "Local Preference", "is_correct": false}, {"id": "B", "text": "MED", "is_correct": true}, {"id": "C", "text": "Origin", "is_correct": false}, {"id": "D", "text": "Next Hop", "is_correct": false}]$$::jsonb, $$MED is advertised to external peers and influences how they send traffic into your AS.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$BGP Fundamentals$$::text, 20.0, 'afe52e157b726d18', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5afe9c0e-a9bb-52f6-bd9c-c706ade06c3c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$What is the purpose of MPLS PHP?$$::text, $$[{"id": "A", "text": "To add a second label", "is_correct": false}, {"id": "B", "text": "To remove the top label before the egress router", "is_correct": true}, {"id": "C", "text": "To encrypt MPLS traffic", "is_correct": false}, {"id": "D", "text": "To enable RSVP", "is_correct": false}]$$::jsonb, $$Penultimate Hop Popping removes the MPLS label one hop before the egress router to reduce its processing.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$MPLS Fundamentals$$::text, 20.0, 'ee07fea225980ca4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0031b457-d831-57e4-b425-078ef697b9a0', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which OSPF area type accepts a default route but no external LSAs?$$::text, $$[{"id": "A", "text": "Standard", "is_correct": false}, {"id": "B", "text": "Stub", "is_correct": true}, {"id": "C", "text": "Backbone", "is_correct": false}, {"id": "D", "text": "Transit", "is_correct": false}]$$::jsonb, $$Stub areas block Type 5 external LSAs and use a default route for external destinations.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$IGP Fundamentals$$::text, 20.0, 'd6fcfe8bbc835f1d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e018fe7-32fb-56c7-9126-a2c5faacacc7', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command displays BGP neighbors on a Junos device?$$::text, $$[{"id": "A", "text": "show bgp summary", "is_correct": true}, {"id": "B", "text": "show route bgp", "is_correct": false}, {"id": "C", "text": "show protocols bgp", "is_correct": false}, {"id": "D", "text": "show bgp database", "is_correct": false}]$$::jsonb, $$'show bgp summary' displays BGP peer sessions, AS numbers, and message counts.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$BGP Fundamentals$$::text, 20.0, '13dd3f94d5c1a88f', true) ON CONFLICT (id) DO NOTHING;
