INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfe77981-8f70-5235-80e0-3fa3ca79e40e', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', $$Which zone type on SRX is typically used for untrusted networks?$$::text, $$[{"id": "A", "text": "Trust", "is_correct": false}, {"id": "B", "text": "Untrust", "is_correct": true}, {"id": "C", "text": "DMZ", "is_correct": false}, {"id": "D", "text": "Mgmt", "is_correct": false}]$$::jsonb, $$The Untrust zone represents untrusted networks such as the Internet on SRX devices.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-sec.html"}$$::text[], $$Zones$$::text, 25.0, 'aed5f0ab2f53c979', true) ON CONFLICT (id) DO NOTHING;
