INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('416b40e0-341e-5e84-9f6f-874e935aef7a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', $$Which IPsec mode encrypts the entire original IP packet?$$::text, $$[{"id": "A", "text": "Transport mode", "is_correct": false}, {"id": "B", "text": "Tunnel mode", "is_correct": true}, {"id": "C", "text": "AH mode", "is_correct": false}, {"id": "D", "text": "ESP mode", "is_correct": false}]$$::jsonb, $$IPsec tunnel mode encapsulates and encrypts the entire original IP packet. Transport mode encrypts only the payload.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sec.html"}$$::text[], $$IPsec VPNs$$::text, 15.0, '8d5703ba3306d243', true) ON CONFLICT (id) DO NOTHING;
