INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95c6ef78-60f4-5b2b-a6ba-e0a02f88b990', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', $$Which VPN topology connects every site to every other site directly?$$::text, $$[{"id": "A", "text": "Hub-and-spoke", "is_correct": false}, {"id": "B", "text": "Full mesh", "is_correct": true}, {"id": "C", "text": "Point-to-point", "is_correct": false}, {"id": "D", "text": "Remote access", "is_correct": false}]$$::jsonb, $$A full-mesh VPN topology has direct tunnels between every pair of sites.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sec.html"}$$::text[], $$IPsec VPNs$$::text, 15.0, 'f85026c08a85444b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae2a855e-2cb5-5300-8fc2-a068d80eaa29', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', $$Which security feature authenticates users before allowing network access?$$::text, $$[{"id": "A", "text": "Firewall filter", "is_correct": false}, {"id": "B", "text": "802.1X", "is_correct": true}, {"id": "C", "text": "NAT", "is_correct": false}, {"id": "D", "text": "VLAN", "is_correct": false}]$$::jsonb, $$802.1X provides port-based network access control, authenticating users or devices before granting access.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sec.html"}$$::text[], $$Access Control$$::text, 15.0, '0aad09c88b92a533', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e10dc90-cb59-5fc1-a221-b7f0edc32a7f', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'remember', $$Which SRX feature provides intrusion detection and prevention?$$::text, $$[{"id": "A", "text": "AppID", "is_correct": false}, {"id": "B", "text": "IDP", "is_correct": true}, {"id": "C", "text": "UTM", "is_correct": false}, {"id": "D", "text": "Screens", "is_correct": false}]$$::jsonb, $$Intrusion Detection and Prevention (IDP) inspects traffic for known attacks and takes action.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sec.html"}$$::text[], $$Advanced Security$$::text, 15.0, 'e8b2545c24e3748a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddce082e-a8de-5c52-ae82-017b62c16938', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', $$Which authentication protocol is commonly used with 802.1X?$$::text, $$[{"id": "A", "text": "RADIUS", "is_correct": true}, {"id": "B", "text": "TACACS+", "is_correct": false}, {"id": "C", "text": "LDAP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]$$::jsonb, $$RADIUS is the most common authentication server protocol used with 802.1X.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sec.html"}$$::text[], $$Access Control$$::text, 15.0, 'd69d029b7c125e73', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cadb610a-c9d0-574c-b8a8-79c707a4555c', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', $$What does UTM stand for in SRX?$$::text, $$[{"id": "A", "text": "Unified Threat Management", "is_correct": true}, {"id": "B", "text": "Universal Traffic Monitoring", "is_correct": false}, {"id": "C", "text": "Unified Traffic Manager", "is_correct": false}, {"id": "D", "text": "User Threat Management", "is_correct": false}]$$::jsonb, $$UTM (Unified Threat Management) includes antivirus, antispam, and web filtering features on SRX.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sec.html"}$$::text[], $$UTM$$::text, 10.0, 'ad56cdeee89cd48a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('737d4e6a-9664-5620-a9dc-9c843b2e6f2d', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'remember', $$Which EVPN route type advertises MAC/IP reachability?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": true}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 4", "is_correct": false}]$$::jsonb, $$EVPN Type 2 routes advertise MAC and IP reachability information.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-dc.html"}$$::text[], $$EVPN$$::text, 15.0, 'dda86f38f09155b2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('515c6753-de24-578f-8a1d-40c2d2db6630', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', $$Which protocol is typically used as the overlay encapsulation in EVPN-VXLAN fabrics?$$::text, $$[{"id": "A", "text": "MPLS", "is_correct": false}, {"id": "B", "text": "VXLAN", "is_correct": true}, {"id": "C", "text": "GRE", "is_correct": false}, {"id": "D", "text": "IPsec", "is_correct": false}]$$::jsonb, $$VXLAN is the common encapsulation for EVPN data center overlays.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-dc.html"}$$::text[], $$VXLAN$$::text, 15.0, '942228d1c263cb9e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ec94473-0265-5ab6-bf81-82113929992e', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', $$Which feature prevents Layer 2 loops in an EVPN-VXLAN fabric?$$::text, $$[{"id": "A", "text": "STP", "is_correct": false}, {"id": "B", "text": "Split horizon", "is_correct": true}, {"id": "C", "text": "VRRP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]$$::jsonb, $$EVPN uses split-horizon and designated forwarder election to prevent Layer 2 loops, reducing reliance on STP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-dc.html"}$$::text[], $$EVPN$$::text, 15.0, '5e677e0293c98d2b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a072ae89-cd00-56c7-b607-565098d66b4a', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', $$Which Junos feature provides active-active multihoming in EVPN?$$::text, $$[{"id": "A", "text": "Single-homed ES", "is_correct": false}, {"id": "B", "text": "All-active multihoming", "is_correct": true}, {"id": "C", "text": "VRRP", "is_correct": false}, {"id": "D", "text": "MC-LAG only", "is_correct": false}]$$::jsonb, $$EVPN all-active multihoming allows multiple PEs to forward traffic simultaneously for an Ethernet segment.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-dc.html"}$$::text[], $$EVPN Multihoming$$::text, 15.0, 'e071b3a68072bf01', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4c67926-e4cf-598a-b695-59659b118532', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'apply', $$Which command displays VXLAN tunnel endpoints?$$::text, $$[{"id": "A", "text": "show vxlan tunnel", "is_correct": true}, {"id": "B", "text": "show evpn vxlan", "is_correct": false}, {"id": "C", "text": "show route vxlan", "is_correct": false}, {"id": "D", "text": "show ethernet-switching vxlan", "is_correct": false}]$$::jsonb, $$'show vxlan tunnel' displays VXLAN tunnel endpoint information on Junos devices.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-dc.html"}$$::text[], $$VXLAN$$::text, 15.0, 'a53ffa665aab3639', true) ON CONFLICT (id) DO NOTHING;
