INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9c34555-ef58-5ebd-8057-2b76ab82512d', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', $$Which protocol is used for underlay routing in a BGP-based EVPN fabric?$$::text, $$[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "EBGP", "is_correct": true}, {"id": "D", "text": "RIP", "is_correct": false}]$$::jsonb, $$EBGP is commonly used for the underlay in EVPN-VXLAN fabrics due to simple peer relationships and rich policy.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-dc.html"}$$::text[], $$Underlay$$::text, 15.0, '18a51dda748af281', true) ON CONFLICT (id) DO NOTHING;
